const SUPABASE_CONFIG = {
  table: "poi_review_test_results",
  testBatchId: "kasai-rinkai-20260625-v1",
  parkKey: "kasai-rinkai",
  parkName: "葛西臨海公園"
};

const ROLES = {
  "KAICHO-LOCAL": { name:"会長", mode:"local", label:"現地視点", instruction:"現地で人が安全に集まれるか、休めるか、歩きやすいかを基準に判定してください。", showMeta:true },
  "JUNPOKO-NAME": { name:"ジュンポコサン", mode:"name", label:"名前だけ判定", instruction:"POI名だけを見て、どんな使われ方に向いていそうかを判定してください。地図や現地情報は見ない前提です。", showMeta:false },
  "RUTO-NAME": { name:"ると君", mode:"name", label:"名前だけ判定", instruction:"POI名だけを見て、どんな使われ方に向いていそうかを判定してください。地図や現地情報は見ない前提です。", showMeta:false },
  "NAKANO-WAYFARER": { name:"中野さん", mode:"wayfarer", label:"Wayfarer視点", instruction:"Wayfarer品質目線で、POI名として妥当か、場所の意味が明確か、学習データに使えるかを判定してください。", showMeta:true }
};

const DECISIONS = [
  { code:"REST", label:"休憩向き", help:"座る・休む・日陰・トイレ・東屋など" },
  { code:"STAY", label:"滞在向き", help:"集合・待機・交流・写真・広場・ランドマーク" },
  { code:"LOOP", label:"回遊向き", help:"園路・橋・通路・導線・歩きながら巡る場所" },
  { code:"CAUTION", label:"注意が必要", help:"水辺・狭い場所・混雑・車道近く・夜間不安" },
  { code:"HOLD", label:"保留：判断材料不足", help:"あとで見れば使えるかもしれない", extraClass:"hold" },
  { code:"EXCLUDE", label:"除外：学習対象外", help:"情報が増えても使わない・学習ノイズ", extraClass:"exclude" }
];

let currentRoleKey = null;
let currentIndex = 0;
let showOnlyUnanswered = false;

const qs = (s)=>document.querySelector(s);
const qsa = (s)=>Array.from(document.querySelectorAll(s));
const storageKey = ()=> currentRoleKey ? `kasai-review-v11-${currentRoleKey}` : "kasai-review-v11";
const nowIso = ()=> new Date().toISOString();

function loadAnswers(){
  if(!currentRoleKey) return {};
  try { return JSON.parse(localStorage.getItem(storageKey()) || "{}"); } catch(e) { return {}; }
}
function saveAnswers(answers){ localStorage.setItem(storageKey(), JSON.stringify(answers)); }
function getAnswer(id){ return loadAnswers()[id] || null; }
function setAnswer(id, patch){
  const answers = loadAnswers();
  answers[id] = { ...(answers[id]||{}), ...patch, updatedAt: nowIso() };
  saveAnswers(answers);
}

function init(){
  renderRoles();
  renderDecisionButtons();
  bindEvents();
  const invite = new URLSearchParams(location.search).get("invite");
  if(invite && ROLES[invite]) selectRole(invite);
}

function bindEvents(){
  qs('#changeRoleBtn').addEventListener('click',()=>{ currentRoleKey=null; qs('#rolePanel').hidden=false; hideReview(); });
  qs('#prevBtn').addEventListener('click',prevPoi);
  qs('#nextBtn').addEventListener('click',nextPoi);
  qs('#bottomPrevBtn').addEventListener('click',prevPoi);
  qs('#bottomUnansweredBtn').addEventListener('click',goNextUnanswered);
  qs('#bottomExportBtn').addEventListener('click',()=>{ renderExport(); qs('#exportCard').scrollIntoView({behavior:'smooth',block:'start'}); });
  qs('#goUnansweredBtn').addEventListener('click',goNextUnanswered);
  qs('#showAllBtn').addEventListener('click',()=>{ showOnlyUnanswered=false; renderList(); });
  qs('#showUnansweredBtn').addEventListener('click',()=>{ showOnlyUnanswered=true; renderList(); });
  qs('#memoInput').addEventListener('input',()=>{ const poi=POIS[currentIndex]; setAnswer(poi.id, { memo: qs('#memoInput').value }); renderProgress(); renderList(); renderExport(); });
  qs('#submitResultBtn').addEventListener('click',submitToSupabase);
  qs('#copyResultBtn').addEventListener('click',copyResult);
  qs('#downloadResultBtn').addEventListener('click',downloadResult);
  qs('#resetBtn').addEventListener('click',resetCurrentRole);
  qs('#guideToggle').addEventListener('click',()=>toggleBlock('#guideToggle','#guideBody'));
  qs('#listToggle').addEventListener('click',()=>toggleBlock('#listToggle','#listBody'));
}

function toggleBlock(btnSel, bodySel){
  const btn=qs(btnSel); const body=qs(bodySel);
  const open = body.hidden;
  body.hidden = !open;
  btn.setAttribute('aria-expanded', String(open));
}

function renderRoles(){
  const grid=qs('#roleGrid');
  grid.innerHTML='';
  Object.entries(ROLES).forEach(([key,role])=>{
    const b=document.createElement('button');
    b.className='role-card';
    b.type='button';
    b.innerHTML=`<strong>${role.name}</strong><span>${role.label}</span><span>${role.instruction}</span>`;
    b.addEventListener('click',()=>selectRole(key));
    grid.appendChild(b);
  });
}

function selectRole(key){
  currentRoleKey=key;
  currentIndex=0;
  qs('#rolePanel').hidden=true;
  qsa('.role-card').forEach(x=>x.classList.remove('active'));
  showReview();
  renderAll();
}

function hideReview(){
  ['#statusCard','#guideCard','#reviewCard','#listCard','#exportCard','#bottomNav'].forEach(id=>qs(id).hidden=true);
}
function showReview(){
  ['#statusCard','#guideCard','#reviewCard','#listCard','#exportCard','#bottomNav'].forEach(id=>qs(id).hidden=false);
}

function renderAll(){ renderStatus(); renderPoi(); renderProgress(); renderList(); renderExport(); }
function renderStatus(){
  const role=ROLES[currentRoleKey];
  qs('#currentRole').textContent = `${role.name} / ${role.label}`;
  qs('#roleInstruction').textContent = role.instruction;
}

function renderDecisionButtons(){
  const wrap=qs('#decisionButtons');
  wrap.innerHTML='';
  DECISIONS.forEach(d=>{
    const b=document.createElement('button');
    b.type='button';
    b.className=`decision-btn ${d.extraClass||''}`;
    b.dataset.code=d.code;
    b.innerHTML=`<strong>${d.label}</strong><small>${d.help}</small>`;
    b.addEventListener('click',()=>chooseDecision(d.code));
    wrap.appendChild(b);
  });
}

function chooseDecision(code){
  const poi = POIS[currentIndex];
  const d = DECISIONS.find(x => x.code === code);

  setAnswer(poi.id, {
    decisionCode: code,
    decisionLabel: d.label,
    memo: qs('#memoInput').value || ''
  });

  renderPoi();
  renderProgress();
  renderList();
  renderExport();

  const hint = qs('#afterDecisionHint');
  if (hint) {
    hint.textContent =
      '判定を保存しました。必要ならメモを書いてから「次のPOIへ」を押してください。';
    hint.hidden = false;
  }
}
function saveCurrentMemo(){
  const poi = POIS[currentIndex];
  if(!poi) return;

  const memoInput = qs('#memoInput');
  if(!memoInput) return;

  const current = getAnswer(poi.id) || {};

  setAnswer(poi.id, {
    ...current,
    memo: memoInput.value || ''
  });
}
function renderPoi(){
  const poi=POIS[currentIndex];
  const role=ROLES[currentRoleKey];
  const ans=getAnswer(poi.id);
  qs('#poiCounter').textContent=`${currentIndex+1} / ${POIS.length}`;
  qs('#poiName').textContent=poi.name || '(名称なし)';
  const meta=[];
  if(role.showMeta){
    meta.push(`<div class="meta-row"><b>種別</b><span>${escapeHtml(poi.type||'不明')}</span></div>`);
    meta.push(`<div class="meta-row"><b>座標</b><span>${escapeHtml(poi.lat||'')} , ${escapeHtml(poi.lng||'')}</span></div>`);
    if(poi.mapUrl) meta.push(`<div class="meta-row"><b>地図</b><a href="${poi.mapUrl}" target="_blank" rel="noopener">Googleマップで開く</a></div>`);
  } else {
    meta.push(`<div class="meta-row"><b>表示制限</b><span>名前だけ判定のため、地図・座標・種別は非表示</span></div>`);
  }
  qs('#metaBox').innerHTML=meta.join('');
  qs('#memoInput').value=ans?.memo || '';
  const nextBtn = qs('#nextBtn');
if(nextBtn){
  nextBtn.textContent =
    currentIndex >= POIS.length - 1
      ? '提出画面へ'
      : '次のPOIへ';
}
  qsa('.decision-btn').forEach(btn=>btn.classList.toggle('selected', ans?.decisionCode === btn.dataset.code));
}

function renderProgress(){
  const answers=loadAnswers();
  const done=POIS.filter(p=>answers[p.id]?.decisionCode).length;
  qs('#progressText').textContent=`${done} / ${POIS.length}`;
  qs('#progressBar').style.width=`${Math.round(done/POIS.length*100)}%`;
  qs('#listSummary').textContent=`${done}件完了 / 未判定${POIS.length-done}件`;
}

function renderList(){
  const answers=loadAnswers();
  const list=qs('#poiList');
  list.innerHTML='';
  POIS.forEach((p,i)=>{
    const ans=answers[p.id];
    if(showOnlyUnanswered && ans?.decisionCode) return;
    const btn=document.createElement('button');
    btn.type='button';
    btn.className=`poi-item ${ans?.decisionCode?'done':''} ${i===currentIndex?'active':''}`;
    const label=ans?.decisionLabel || '未判定';
    btn.innerHTML=`<span><b>${i+1}. ${escapeHtml(p.name)}</b></span><span class="mark">${escapeHtml(label)}</span>`;
    btn.addEventListener('click',()=>{ currentIndex=i; renderPoi(); renderList(); qs('#reviewCard').scrollIntoView({behavior:'smooth',block:'start'}); });
    list.appendChild(btn);
  });
}

function nextPoi(){
  saveCurrentMemo();

  if(currentIndex >= POIS.length - 1){
    renderProgress();
    renderList();
    renderExport();

    const exportCard = qs('#exportCard');
    if(exportCard){
      exportCard.scrollIntoView({
        behavior: 'smooth',
        block: 'start'
      });
    }

    return;
  }

  currentIndex++;

  renderPoi();
  renderProgress();
  renderList();
  renderExport();

  window.scrollTo({
    top: 0,
    behavior: 'smooth'
  });
}
function prevPoi(){ if(currentIndex>0){ currentIndex--; renderPoi(); renderProgress(); renderList(); window.scrollTo({top:0,behavior:'smooth'}); } }
function goNextUnanswered(){
  const answers=loadAnswers();
  const start=currentIndex+1;
  let idx=POIS.findIndex((p,i)=> i>=start && !answers[p.id]?.decisionCode);
  if(idx<0) idx=POIS.findIndex(p=>!answers[p.id]?.decisionCode);
  if(idx>=0){ currentIndex=idx; renderPoi(); renderList(); qs('#reviewCard').scrollIntoView({behavior:'smooth',block:'start'}); }
  else alert('未判定はありません。提出画面へ進めます。');
}

function normalizeName(name){ return String(name||'').normalize('NFKC').trim().replace(/\s+/g,' '); }
function buildPoiUuid(id){
  return `00000000-0000-4000-8000-${String(id).padStart(12,'0')}`;
}
function answeredPois(){
  const answers=loadAnswers();
  return POIS.filter(p=>answers[p.id]?.decisionCode).map(p=>({ poi:p, answer:answers[p.id] }));
}
function unansweredPois(){
  const answers = loadAnswers();

  return POIS.filter(p => {
    return !answers[p.id]?.decisionCode;
  });
}

function getPoiNumber(poi){
  return POIS.findIndex(p => p.id === poi.id) + 1;
}

function getPoiName(poi){
  return poi.name || poi.poiName || poi.title || poi.normalized_name || `POI ${poi.id}`;
}
function buildSupabaseRows(){
  const role=ROLES[currentRoleKey];
  return answeredPois().map(({poi, answer})=>({
    test_batch_id: SUPABASE_CONFIG.testBatchId,
    park_key: SUPABASE_CONFIG.parkKey,
    park_name: SUPABASE_CONFIG.parkName,
    source_queue_id: buildPoiUuid(poi.id),
    poi_name: poi.name || '',
    normalized_name: normalizeName(poi.name),
    sample_lat: poi.lat ? Number(poi.lat) : null,
    sample_lng: poi.lng ? Number(poi.lng) : null,
    reviewer_name: role.name,
    reviewer_type: role.mode,
    selected_category: answer.decisionCode || '',
    confidence: null,
    review_note: answer.memo || '',
    reviewed_at: answer.updatedAt || nowIso()
  }));
}
function buildBackupResult(){
  const role=ROLES[currentRoleKey];
  const answers=loadAnswers();
  return {
    testId: SUPABASE_CONFIG.testBatchId,
    target: SUPABASE_CONFIG.parkName,
    version:'v14-source-queue-uuid-fix',
    exportedAt:nowIso(),
    roleKey:currentRoleKey,
    reviewer:role.name,
    roleLabel:role.label,
    reviewerType:role.mode,
    total:POIS.length,
    answered:answeredPois().length,
    results:POIS.map(p=>({
      id:p.id,
      name:p.name,
      decisionCode:answers[p.id]?.decisionCode || '',
      decisionLabel:answers[p.id]?.decisionLabel || '',
      memo:answers[p.id]?.memo || '',
      updatedAt:answers[p.id]?.updatedAt || ''
    }))
  };
}function renderExport(){
  if(!currentRoleKey) return;

  const result = buildBackupResult();
  const output = qs('#resultOutput');

  if(output) {
    output.value = JSON.stringify(result, null, 2);
  }

  const progress = qs('#submitProgress');

  if(progress) {
    progress.textContent = `${result.answered} / ${result.total} 件判定済み`;
  }

  renderMissingBox();
}
function renderMissingBox(){
  const exportCard = qs('#exportCard');
  if(!exportCard) return;

  let box = qs('#missingBox');

  if(!box){
    box = document.createElement('div');
    box.id = 'missingBox';
    box.className = 'missing-box';

    const exportActions = qs('.export-actions');

    if(exportActions){
      exportActions.insertAdjacentElement('beforebegin', box);
    }else{
      exportCard.appendChild(box);
    }
  }

  const missing = unansweredPois();

  if(missing.length === 0){
    box.hidden = false;
    box.innerHTML = `
      <p class="missing-ok">全件判定済みです。このまま送信できます。</p>
    `;
    return;
  }

  const listHtml = missing
  .map(poi => {
    return `${getPoiNumber(poi)}番：${escapeHtml(getPoiName(poi))}`;
  })
  .join('<br>');

  box.hidden = false;
  box.innerHTML = `
    <p class="missing-alert">未判定が ${missing.length} 件あります。</p>
    <p class="missing-list">${listHtml}</p>
    <button type="button" class="primary-btn" id="goMissingBtn">
      未判定のPOIへ移動
    </button>
  `;

  const goMissingBtn = qs('#goMissingBtn');

  if(goMissingBtn){
    goMissingBtn.addEventListener('click', () => {
      const first = missing[0];
      const index = POIS.findIndex(p => p.id === first.id);

      if(index >= 0){
        saveCurrentMemo();

        currentIndex = index;

        renderPoi();
        renderProgress();
        renderList();
        renderExport();

        qs('#reviewCard').scrollIntoView({
          behavior: 'smooth',
          block: 'start'
        });
      }
    });
  }
}
function setSubmitStatus(type, message){
  const box=qs('#submitStatus');
  box.hidden=false;
  box.className=`submit-status ${type||''}`;
  box.textContent=message;
}
function isSupabaseConfigured(){
  return !!window.campsiteSupabase;
}
async function submitToSupabase(){
  renderExport();
  const rows=buildSupabaseRows();
  const unanswered=POIS.length-rows.length;
  if(rows.length===0){ alert('まだ判定がありません。1件以上判定してから送信してください。'); return; }
  if(unanswered>0 && !confirm(`未判定が${unanswered}件あります。このまま送信しますか？`)) return;
  if(!isSupabaseConfigured()){
    setSubmitStatus('error','Supabaseに接続できません。js/lab-supabase.js の読み込みを確認してください。');
    return;
  }
  const btn=qs('#submitResultBtn');
  btn.disabled=true;
  btn.textContent='送信中...';
  setSubmitStatus('sending','送信中です。画面を閉じずにお待ちください。');
  try{
    const { error } = await window.campsiteSupabase
      .from(SUPABASE_CONFIG.table)
      .upsert(rows, {
        onConflict: 'test_batch_id,source_queue_id,reviewer_name,reviewer_type'
      });
    if(error) throw error;
    localStorage.setItem(`${storageKey()}_lastSubmittedAt`, nowIso());
    setSubmitStatus('ok',`送信しました。${rows.length}件の判定が保存されました。`);
    if(navigator.vibrate) navigator.vibrate([60, 40, 90]);
  }catch(err){
    console.error('Supabase submit error:', err);
    const detail = [
      err?.message ? `message: ${err.message}` : '',
      err?.code ? `code: ${err.code}` : '',
      err?.details ? `details: ${err.details}` : '',
      err?.hint ? `hint: ${err.hint}` : ''
    ].filter(Boolean).join(' / ');
    setSubmitStatus(
      'error',
      detail
        ? `送信に失敗しました。${detail}`
        : '送信に失敗しました。F12のConsoleに出たエラーを確認してください。'
    );
  }finally{
    btn.disabled=false;
    btn.textContent='送信する';
  }
}
async function copyResult(){
  renderExport();
  const text=qs('#resultOutput').value;
  try{
    await navigator.clipboard.writeText(text);
    alert('予備データをコピーしました。');
  }catch(e){
    qs('#resultOutput').select();
    document.execCommand('copy');
    alert('予備データをコピーしました。');
  }
}
function downloadResult(){
  renderExport();
  const blob=new Blob([qs('#resultOutput').value],{type:'application/json'});
  const a=document.createElement('a');
  a.href=URL.createObjectURL(blob);
  a.download=`葛西臨海公園_POIレビュー_${currentRoleKey}_backup.json`;
  a.click();
  URL.revokeObjectURL(a.href);
  alert('予備ファイルを保存しました。送信できない時だけ会長に送ってください。');
}
function resetCurrentRole(){ if(confirm('この担当の入力をすべてリセットしますか？')){ localStorage.removeItem(storageKey()); renderAll(); } }
function escapeHtml(s){ return String(s??'').replace(/[&<>"']/g, c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])); }

document.addEventListener('DOMContentLoaded', init);
